wrapper_template:
case "${1:-}" in
  s3-ls)
    aws s3 ls | head -n "$MAX_LINES"
    ;;
  s3-ls-bucket)
    [ -z "${2:-}" ] && { echo "Usage: aws.sh s3-ls-bucket <bucket>" >&2; exit 1; }
    aws s3 ls "s3://$2" --recursive --human-readable | head -n "$MAX_LINES"
    ;;
  s3-get)
    [ -z "${3:-}" ] && { echo "Usage: aws.sh s3-get <bucket> <key>" >&2; exit 1; }
    aws s3 cp "s3://$2/$3" - | head -n "$MAX_LINES"
    ;;
  lambda-ls)
    aws lambda list-functions --query 'Functions[].{Name:FunctionName,Runtime:Runtime,Size:CodeSize}' --output table | head -n "$MAX_LINES"
    ;;
  lambda-invoke)
    [ -z "${2:-}" ] && { echo "Usage: aws.sh lambda-invoke <function> [payload]" >&2; exit 1; }
    aws lambda invoke --function-name "$2" --payload "${3:-'{}'}" --cli-binary-format raw-in-base64-out /dev/stdout 2>/dev/null
    ;;
  cf-ls)
    aws cloudformation list-stacks --query 'StackSummaries[?StackStatus!=`DELETE_COMPLETE`].{Name:StackName,Status:StackStatus}' --output table | head -n "$MAX_LINES"
    ;;
  whoami)
    aws sts get-caller-identity --output json
    ;;
